import{_ as e,c as a,o as l,aM as o}from"./chunks/framework.ByOTD7qd.js";const b=JSON.parse('{"title":"嵌入模型","description":"","frontmatter":{"title":"嵌入模型","date":"2025-11-25T22:00:00.000Z"},"headers":[],"relativePath":"zh/docs/getting-started/embedding-models.md","filePath":"zh/docs/getting-started/embedding-models.md","lastUpdated":null}'),i={name:"zh/docs/getting-started/embedding-models.md"};function d(r,t,n,h,s,c){return l(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="嵌入模型" tabindex="-1">嵌入模型 <a class="header-anchor" href="#嵌入模型" aria-label="Permalink to &quot;嵌入模型&quot;">​</a></h1><p>嵌入模型（Embedding Models）将文本转换为捕捉语义含义的数值向量，从而实现语义搜索、文档相似度和智能上下文检索等强大功能。</p><h2 id="什么是嵌入模型" tabindex="-1">什么是嵌入模型？ <a class="header-anchor" href="#什么是嵌入模型" aria-label="Permalink to &quot;什么是嵌入模型？&quot;">​</a></h2><p>与生成文本响应的聊天模型不同，嵌入模型产生固定长度的数值数组（向量），用于表示文本的含义。这些向量可用于：</p><ul><li><strong>语义搜索</strong>：按含义而非关键词查找内容</li><li><strong>文档相似度</strong>：比较两段文本的相关程度</li><li><strong>上下文检索</strong>：为 AI 对话查找相关信息</li><li><strong>记忆增强</strong>：通过查找相关的过去对话来改善助手记忆</li></ul><h2 id="kelivo-如何使用嵌入" tabindex="-1">Kelivo 如何使用嵌入 <a class="header-anchor" href="#kelivo-如何使用嵌入" aria-label="Permalink to &quot;Kelivo 如何使用嵌入&quot;">​</a></h2><p>Kelivo 在模型选择界面中自动将嵌入模型与聊天模型分开归类。这有助于您：</p><ol><li><strong>识别模型类型</strong>：嵌入模型分组在专门的&quot;嵌入&quot;类别下</li><li><strong>正确选择</strong>：为特定功能选择嵌入模型</li><li><strong>避免混淆</strong>：嵌入模型不能用于常规聊天</li></ol><h3 id="模型类型检测" tabindex="-1">模型类型检测 <a class="header-anchor" href="#模型类型检测" aria-label="Permalink to &quot;模型类型检测&quot;">​</a></h3><p>Kelivo 通过以下方式识别嵌入模型：</p><ul><li>来自供应商的模型类型元数据</li><li>模型 ID 包含 &quot;embedding&quot; 或 &quot;embed&quot;</li></ul><p>查看可用模型时，请查找 <strong>嵌入</strong> 分组来找到这些专用模型。</p><h2 id="支持的嵌入模型" tabindex="-1">支持的嵌入模型 <a class="header-anchor" href="#支持的嵌入模型" aria-label="Permalink to &quot;支持的嵌入模型&quot;">​</a></h2><h3 id="openai" tabindex="-1">OpenAI <a class="header-anchor" href="#openai" aria-label="Permalink to &quot;OpenAI&quot;">​</a></h3><table tabindex="0"><thead><tr><th>模型</th><th>维度</th><th>用途</th></tr></thead><tbody><tr><td><code>text-embedding-3-small</code></td><td>1536</td><td>性价比高，质量好</td></tr><tr><td><code>text-embedding-3-large</code></td><td>3072</td><td>最高质量</td></tr><tr><td><code>text-embedding-ada-002</code></td><td>1536</td><td>旧版，仍然支持</td></tr></tbody></table><p><strong>配置</strong>：</p><ul><li>基础地址：<code>https://api.openai.com/v1</code></li><li>端点：<code>/embeddings</code></li></ul><h3 id="google-gemini" tabindex="-1">Google (Gemini) <a class="header-anchor" href="#google-gemini" aria-label="Permalink to &quot;Google (Gemini)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>模型</th><th>维度</th><th>用途</th></tr></thead><tbody><tr><td><code>text-embedding-004</code></td><td>768</td><td>通用</td></tr><tr><td><code>embedding-001</code></td><td>768</td><td>旧版模型</td></tr></tbody></table><p><strong>配置</strong>：</p><ul><li>使用 Google AI Studio 或 Vertex AI</li><li>通过 Gemini API 提供</li></ul><h3 id="anthropic" tabindex="-1">Anthropic <a class="header-anchor" href="#anthropic" aria-label="Permalink to &quot;Anthropic&quot;">​</a></h3><p>Anthropic 目前不提供独立的嵌入模型。如需与 Claude 配合使用嵌入功能，可以考虑：</p><ul><li>使用 OpenAI 或 Google 嵌入模型</li><li>第三方嵌入服务</li></ul><h3 id="自定义-自托管" tabindex="-1">自定义/自托管 <a class="header-anchor" href="#自定义-自托管" aria-label="Permalink to &quot;自定义/自托管&quot;">​</a></h3><p>许多供应商通过 OpenAI 兼容 API 提供嵌入模型：</p><table tabindex="0"><thead><tr><th>供应商</th><th>常用模型</th></tr></thead><tbody><tr><td>Ollama</td><td><code>nomic-embed-text</code>, <code>mxbai-embed-large</code></td></tr><tr><td>Hugging Face</td><td><code>sentence-transformers/*</code></td></tr><tr><td>Cohere</td><td><code>embed-english-v3.0</code>, <code>embed-multilingual-v3.0</code></td></tr><tr><td>Jina AI</td><td><code>jina-embeddings-v2-base-en</code></td></tr><tr><td>Voyage AI</td><td><code>voyage-large-2</code>, <code>voyage-code-2</code></td></tr></tbody></table><h2 id="设置嵌入模型" tabindex="-1">设置嵌入模型 <a class="header-anchor" href="#设置嵌入模型" aria-label="Permalink to &quot;设置嵌入模型&quot;">​</a></h2><h3 id="步骤-1-添加支持嵌入的供应商" tabindex="-1">步骤 1：添加支持嵌入的供应商 <a class="header-anchor" href="#步骤-1-添加支持嵌入的供应商" aria-label="Permalink to &quot;步骤 1：添加支持嵌入的供应商&quot;">​</a></h3><ol><li><strong>打开设置</strong> → <strong>服务供应商</strong></li><li><strong>添加或选择</strong> 提供嵌入模型的供应商</li><li><strong>确保 API Key 有权</strong> 访问嵌入端点</li></ol><h3 id="步骤-2-获取可用模型" tabindex="-1">步骤 2：获取可用模型 <a class="header-anchor" href="#步骤-2-获取可用模型" aria-label="Permalink to &quot;步骤 2：获取可用模型&quot;">​</a></h3><ol><li><strong>打开供应商设置</strong></li><li><strong>点击&quot;获取模型&quot;</strong> 或&quot;刷新模型&quot;</li><li><strong>查看嵌入分类</strong> 在模型列表中</li><li><strong>验证嵌入模型</strong> 是否出现</li></ol><h3 id="步骤-3-配置功能" tabindex="-1">步骤 3：配置功能 <a class="header-anchor" href="#步骤-3-配置功能" aria-label="Permalink to &quot;步骤 3：配置功能&quot;">​</a></h3><p>嵌入模型被某些 Kelivo 功能自动使用：</p><ul><li><strong>记忆</strong>：用于检索相关上下文</li><li><strong>文档搜索</strong>：当为助手启用时</li><li><strong>语义匹配</strong>：用于查找相似对话</li></ul><h2 id="模型选择建议" tabindex="-1">模型选择建议 <a class="header-anchor" href="#模型选择建议" aria-label="Permalink to &quot;模型选择建议&quot;">​</a></h2><h3 id="通用用途" tabindex="-1">通用用途 <a class="header-anchor" href="#通用用途" aria-label="Permalink to &quot;通用用途&quot;">​</a></h3><p><strong>推荐</strong>：<code>text-embedding-3-small</code>（OpenAI）</p><ul><li>质量和成本的良好平衡</li><li>广泛兼容</li><li>处理速度快</li></ul><h3 id="高精度需求" tabindex="-1">高精度需求 <a class="header-anchor" href="#高精度需求" aria-label="Permalink to &quot;高精度需求&quot;">​</a></h3><p><strong>推荐</strong>：<code>text-embedding-3-large</code>（OpenAI）</p><ul><li>最佳质量嵌入</li><li>每次调用成本较高</li><li>更大的向量维度</li></ul><h3 id="节省成本" tabindex="-1">节省成本 <a class="header-anchor" href="#节省成本" aria-label="Permalink to &quot;节省成本&quot;">​</a></h3><p><strong>推荐</strong>：Google 嵌入模型或自托管选项</p><ul><li>通常每 token 成本更低</li><li>大多数用例质量良好</li><li>可能有使用限制</li></ul><h3 id="专业任务" tabindex="-1">专业任务 <a class="header-anchor" href="#专业任务" aria-label="Permalink to &quot;专业任务&quot;">​</a></h3><table tabindex="0"><thead><tr><th>任务</th><th>推荐模型</th></tr></thead><tbody><tr><td>代码搜索</td><td><code>voyage-code-2</code></td></tr><tr><td>多语言</td><td><code>embed-multilingual-v3.0</code>（Cohere）</td></tr><tr><td>本地/私有</td><td><code>nomic-embed-text</code>（Ollama）</td></tr><tr><td>长文档</td><td>支持 8K+ 上下文的模型</td></tr></tbody></table><h2 id="理解嵌入维度" tabindex="-1">理解嵌入维度 <a class="header-anchor" href="#理解嵌入维度" aria-label="Permalink to &quot;理解嵌入维度&quot;">​</a></h2><p>嵌入维度影响：</p><table tabindex="0"><thead><tr><th>高维度</th><th>低维度</th></tr></thead><tbody><tr><td>捕捉更多语义细节</td><td>处理更快</td></tr><tr><td>准确度更高</td><td>内存使用更少</td></tr><tr><td>需要更多存储</td><td>更具性价比</td></tr><tr><td>相似度计算更慢</td><td>可能丢失细微含义</td></tr></tbody></table><p><strong>典型范围</strong>：</p><ul><li>小型：384-768 维</li><li>中型：1024-1536 维</li><li>大型：2048-3072+ 维</li></ul><h2 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h2><h3 id="_1-保持一致性" tabindex="-1">1. 保持一致性 <a class="header-anchor" href="#_1-保持一致性" aria-label="Permalink to &quot;1. 保持一致性&quot;">​</a></h3><p>对相关操作使用 <strong>相同的嵌入模型</strong>：</p><ul><li>如果用 <code>text-embedding-3-small</code> 嵌入文档，搜索时也使用同一模型</li><li>切换模型会使现有嵌入失效</li></ul><h3 id="_2-文本分块" tabindex="-1">2. 文本分块 <a class="header-anchor" href="#_2-文本分块" aria-label="Permalink to &quot;2. 文本分块&quot;">​</a></h3><p>对于长文档：</p><ul><li>分割成有意义的块（段落、章节）</li><li>典型块大小：256-512 个 token</li><li>块之间包含重叠以保持上下文</li></ul><h3 id="_3-预处理" tabindex="-1">3. 预处理 <a class="header-anchor" href="#_3-预处理" aria-label="Permalink to &quot;3. 预处理&quot;">​</a></h3><p>提高嵌入质量：</p><ul><li>移除不必要的空白</li><li>规范化格式</li><li>考虑为搜索移除停用词</li></ul><h3 id="_4-缓存" tabindex="-1">4. 缓存 <a class="header-anchor" href="#_4-缓存" aria-label="Permalink to &quot;4. 缓存&quot;">​</a></h3><p>嵌入是确定性的：</p><ul><li>为静态内容缓存嵌入</li><li>仅在内容变化时重新嵌入</li><li>节省 API 成本和处理时间</li></ul><h2 id="成本考虑" tabindex="-1">成本考虑 <a class="header-anchor" href="#成本考虑" aria-label="Permalink to &quot;成本考虑&quot;">​</a></h2><p>嵌入模型通常比聊天模型更便宜：</p><table tabindex="0"><thead><tr><th>供应商</th><th>模型</th><th>大约成本</th></tr></thead><tbody><tr><td>OpenAI</td><td>text-embedding-3-small</td><td>$0.02/百万 token</td></tr><tr><td>OpenAI</td><td>text-embedding-3-large</td><td>$0.13/百万 token</td></tr><tr><td>Google</td><td>text-embedding-004</td><td>通常有免费额度</td></tr><tr><td>自托管</td><td>Ollama 模型</td><td>免费（仅计算成本）</td></tr></tbody></table><p><strong>成本优化建议</strong>：</p><ul><li>批量嵌入多个文本</li><li>缓存常用嵌入</li><li>在质量允许时使用较小的模型</li><li>大量使用时考虑自托管</li></ul><h2 id="故障排除" tabindex="-1">故障排除 <a class="header-anchor" href="#故障排除" aria-label="Permalink to &quot;故障排除&quot;">​</a></h2><h3 id="找不到嵌入模型" tabindex="-1">找不到嵌入模型 <a class="header-anchor" href="#找不到嵌入模型" aria-label="Permalink to &quot;找不到嵌入模型&quot;">​</a></h3><ol><li><strong>检查供应商配置</strong>：确保 API Key 有嵌入访问权限</li><li><strong>刷新模型列表</strong>：在供应商设置中点击&quot;获取模型&quot;</li><li><strong>验证模型可用性</strong>：某些供应商需要单独的访问权限</li></ol><h3 id="搜索结果不佳" tabindex="-1">搜索结果不佳 <a class="header-anchor" href="#搜索结果不佳" aria-label="Permalink to &quot;搜索结果不佳&quot;">​</a></h3><ol><li><strong>验证使用相同模型</strong>：嵌入和搜索必须使用同一模型</li><li><strong>检查文本预处理</strong>：格式不一致会影响结果</li><li><strong>调整块大小</strong>：块太大或太小都会降低准确度</li></ol><h3 id="延迟高" tabindex="-1">延迟高 <a class="header-anchor" href="#延迟高" aria-label="Permalink to &quot;延迟高&quot;">​</a></h3><ol><li><strong>使用较小维度</strong>：低维度模型更快</li><li><strong>批量请求</strong>：一次发送多个文本</li><li><strong>考虑本地模型</strong>：Ollama 消除网络延迟</li></ol><h3 id="内存-存储问题" tabindex="-1">内存/存储问题 <a class="header-anchor" href="#内存-存储问题" aria-label="Permalink to &quot;内存/存储问题&quot;">​</a></h3><ol><li><strong>减少维度</strong>：使用较小的嵌入模型</li><li><strong>限制历史</strong>：不要无限期嵌入所有内容</li><li><strong>清理旧嵌入</strong>：删除过期的嵌入内容</li></ol><h2 id="与-kelivo-功能集成" tabindex="-1">与 Kelivo 功能集成 <a class="header-anchor" href="#与-kelivo-功能集成" aria-label="Permalink to &quot;与 Kelivo 功能集成&quot;">​</a></h2><h3 id="记忆功能" tabindex="-1">记忆功能 <a class="header-anchor" href="#记忆功能" aria-label="Permalink to &quot;记忆功能&quot;">​</a></h3><p>当为助手启用记忆时：</p><ol><li>从对话中提取重要事实</li><li>事实被嵌入以进行语义检索</li><li>根据对话上下文检索相关记忆</li><li>检索到的记忆包含在提示词中</li></ol><h3 id="未来功能" tabindex="-1">未来功能 <a class="header-anchor" href="#未来功能" aria-label="Permalink to &quot;未来功能&quot;">​</a></h3><p>Kelivo 可能将嵌入用于：</p><ul><li>RAG（检索增强生成）</li><li>文档问答</li><li>知识库搜索</li><li>对话搜索</li></ul><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li>配置支持嵌入的 <a href="/zh/docs/providers/openai">AI 供应商</a></li><li>为助手启用 <a href="/zh/docs/assistant/memory">记忆</a> 功能</li><li>了解 <a href="/zh/docs/assistant/basics">助手基础</a> 的完整配置</li></ul>',88)])])}const u=e(i,[["render",d]]);export{b as __pageData,u as default};
